#include <stdio.h>
#include <stdlib.h>
#include <errno.h>

int main(int argc, char *argv[])
{
    /* NO_INPUT */
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    /* Parse input */
    char *endptr = NULL;
    errno = 0;
    long long n = strtoll(argv[1], &endptr, 10);
    if (endptr == argv[1] || *endptr != '\0' || errno == ERANGE) {
        puts("BAD_INPUT");
        return 0;
    }

    /* Basic range checks */
    if (n < 1) {
        puts("BAD_INPUT");
        return 0;
    }
    if (n > 1000000000LL) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    const long long STEP_LIMIT = 1000000LL;          // 1,000,000 steps
    const long long OVERFLOW_GUARD = 1000000000000000LL; // 1e15

    long long steps = 0;
    long long cur = n;

    while (1) {
        if (cur == 1) {
            printf("n=%lld steps=%lld\n", n, steps);
            break;
        }
        if (steps > STEP_LIMIT) {
            puts("STEP_LIMIT_EXCEEDED");
            break;
        }
        if (cur > OVERFLOW_GUARD) {
            puts("OVERFLOW_GUARD");
            break;
        }
        if (cur & 1LL) {
            cur = cur * 3 + 1;
        } else {
            cur = cur >> 1;
        }
        ++steps;
    }
    return 0;
}
